import java.util.HashMap;
import java.util.Map;

/**
 * Disease that can spread between animals by animals eating infected actors and through birth meaning the
 * parents and and child get each others' diseases.
 * The disease affects different animals with different multipliers, and the disease can be created
 * onto an actor during the start of the simulation.
 *
 * @version 27.02.22
 */
public class Disease
{
    private String name;
    private boolean spreadByBirth;
    private boolean spreadByEating; 
    //actors name as the string, and the disease multiplier as the double
    private Map<String, Double> actorsAffected;
    //actors name as string, the probability of the animal starting with the disease as the double
    private Map<String, Double> startingActors;

    /**
     * Creates the disease and sets it name, and how it spreads, who it can spread to and
     * which actor it starts with.
     * @param name The name of the disease
     * @param spreadByBirth Whether or not the disease is spread by birth.
     * @param spreadByEating Whether or not the disease is spread by eating.
     */
    public Disease(String name, boolean spreadByBirth,boolean spreadByEating)
    {
        this.name = name;
        this.spreadByBirth = spreadByBirth;
        this.spreadByEating = spreadByEating;
        actorsAffected = new HashMap<>();
        startingActors = new HashMap<>();
    }

    /**
     * Returns the String name of the disease.
     * @return The String name of the disease.
     */
    public String getName()
    {
        return name;
    }

    /**
     * Used to return if the disease is spread by birth,
     * the child gets their parents disease and the mate also gets the disease during 
     * birth
     * @return true if it does spread by birth
     */
    public boolean isSpreadByBirth()
    {
        return spreadByBirth;
    }

    /**
     * Used to return if the disease is spread by eating,
     * predators can be infected by eating an infected actor
     * @return true if it does spread by eating
     */
    public boolean isSpreadByEating()
    {
        return spreadByEating;
    }

    /**
     * Add an actor affected by this disease.
     * @param actorName The actor name.
     * @param severity The disease severity multiplier.
     * @return This disease for chained configuration.
     */
    public Disease addAffectedActor(String actorName, double severity)
    {
        actorsAffected.put(actorName, severity);
        return this;
    }

    /**
     * Add an actor that can start the simulation with this disease.
     * @param actorName The actor name.
     * @param probability The probability of starting with the disease.
     * @return This disease for chained configuration.
     */
    public Disease addStartingActor(String actorName, double probability)
    {
        startingActors.put(actorName, probability);
        return this;
    }

    /**
     * Check whether this disease affects an actor.
     * @param actorName The actor name.
     * @return true if the disease affects the actor.
     */
    public boolean affectsActor(String actorName)
    {
        return actorsAffected.containsKey(actorName);
    }

    /**
     * Return the disease severity multiplier for an actor.
     * @param actorName The actor name.
     * @return The severity multiplier, or 1.0 if the actor is unaffected.
     */
    public double getSeverityFor(String actorName)
    {
        Double severity = actorsAffected.get(actorName);
        if(severity == null) {
            return 1.0;
        }
        return severity;
    }

    /**
     * Check whether an actor can start the simulation with this disease.
     * @param actorName The actor name.
     * @return true if the actor can start with this disease.
     */
    public boolean canStartInActor(String actorName)
    {
        return startingActors.containsKey(actorName);
    }

    /**
     * Return the probability that an actor starts with this disease.
     * @param actorName The actor name.
     * @return The starting probability, or 0.0 if the actor cannot start with it.
     */
    public double getStartingProbabilityFor(String actorName)
    {
        Double probability = startingActors.get(actorName);
        if(probability == null) {
            return 0.0;
        }
        return probability;
    }

    /**
     * returns the map of the actors affected by the disease
     * @return Map<String,Double> of the actors affected
     */
    public Map<String, Double> getActorsAffectedMap()
    {
        return actorsAffected;
    }

     /**
     * returns the map of the actors that start with the disease
     * @return Map<String,Double> of the actors that start with it
     */
    public Map<String, Double> getStartingActorsMap()
    {
        return startingActors;
    }
}

import java.io.Serializable;

/**
 * Provide a counter for a participant in the simulation.
 * This includes an identifying string and a count of how
 * many participants of this type currently exist within 
 * the simulation.
 *
 * @version 2016.02.29
 */
public class Counter implements Serializable
{
    private static final long serialVersionUID = 1L;

    // A name for this type of simulation participant
    private String name;
    // How many of this type exist in the simulation.
    private int count;

    /**
     * Provide a name for one of the simulation types.
     * @param name  A name, e.g. "Fox".
     */
    public Counter(String name)
    {
        this.name = name;
        count = 0;
    }

    /**
     * @return The short description of this type.
     */
    public String getName()
    {
        return name;
    }

    /**
     * @return The current count for this type.
     */
    public int getCount()
    {
        return count;
    }

    /**
     * Increment the current count by one.
     */
    public void increment()
    {
        count++;
    }

    /**
     * Reset the current count to zero.
     */
    public void reset()
    {
        count = 0;
    }
}
/**
 * Time class that deals with the time that is passed for each step taken 
 * Used for the day and night cycle
 *
 * @version 27.02.22
 */
public class Time
{
    private int time;
    // How much time will increment by for each step
    private int timeStep;

    /**
     * Creates the time, sets it to 0 and takes how much time will increment by
     * @param timeStep How much time will increment by for each step
     */
    public Time(int timeStep)
    {
        time = 0;
        this.timeStep = timeStep;
    }

    /**
     * Used to increment the time by the time step, keeps it at range 0-24
     * to simulate a 24hr time system
     */
    public void incrementTime()
    {
        time = (time + timeStep) % 24;
    }

    /**
     * Used to check if it is day which is true or if its night
     * @return true if day, false if it is night
     */
    public boolean isDay()
    {
        return time < 18 && time > 6;
    }
}
